```csharp
using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UIElements;

public class GameOverScreenUI : MonoBehaviour
{
    private const string BestScoreKey = "BestScore";

    [SerializeField] private string menuSceneName = "MainMenu";
    [SerializeField] private float fadeDuration = 1.0f;

    private VisualElement overlay;
    private Label scoreLabel;
    private Label bestLabel;
    private Coroutine fadeRoutine;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.pickingMode = PickingMode.Ignore;

        overlay = new VisualElement();
        overlay.style.position = Position.Absolute;
        overlay.style.left = 0;
        overlay.style.right = 0;
        overlay.style.top = 0;
        overlay.style.bottom = 0;
        overlay.style.alignItems = Align.Center;
        overlay.style.justifyContent = Justify.Center;
        overlay.style.backgroundColor = new Color(0.05f, 0f, 0f, 0.85f);
        overlay.style.opacity = 0f;
        overlay.style.display = DisplayStyle.None;
        root.Add(overlay);

        Label title = new Label("GAME OVER");
        title.style.fontSize = 88;
        title.style.color = new Color(0.9f, 0.2f, 0.2f, 1f);
        title.style.marginBottom = 30;
        overlay.Add(title);

        scoreLabel = new Label("Score: 0");
        scoreLabel.style.fontSize = 44;
        scoreLabel.style.color = Color.white;
        overlay.Add(scoreLabel);

        bestLabel = new Label("Best: 0");
        bestLabel.style.fontSize = 34;
        bestLabel.style.color = new Color(1f, 0.85f, 0.3f, 1f);
        bestLabel.style.marginBottom = 40;
        overlay.Add(bestLabel);

        Button retry = new Button(() =>
        {
            Time.timeScale = 1f;
            SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex);
        });
        retry.text = "Retry";
        StyleButton(retry);
        overlay.Add(retry);

        Button menu = new Button(() =>
        {
            Time.timeScale = 1f;
            SceneManager.LoadScene(menuSceneName);
        });
        menu.text = "Main Menu";
        StyleButton(menu);
        overlay.Add(menu);
    }

    public void Show(int finalScore)
    {
        int best = PlayerPrefs.GetInt(BestScoreKey, 0);
        if (finalScore > best)
        {
            best = finalScore;
            PlayerPrefs.SetInt(BestScoreKey, best);
            PlayerPrefs.Save();
        }

        scoreLabel.text = "Score: " + finalScore;
        bestLabel.text = "Best: " + best;
        overlay.style.display = DisplayStyle.Flex;
        if (fadeRoutine != null) StopCoroutine(fadeRoutine);
        fadeRoutine = StartCoroutine(FadeIn());
    }

    private IEnumerator FadeIn()
    {
        float t = 0f;
        while (t < fadeDuration)
        {
            t += Time.unscaledDeltaTime;
            overlay.style.opacity = Mathf.Clamp01(t / fadeDuration);
            yield return null;
        }
        overlay.style.opacity = 1f;
    }

    private static void StyleButton(Button button)
    {
        button.style.width = 320;
        button.style.height = 64;
        button.style.fontSize = 28;
        button.style.marginBottom = 14;
        button.style.color = Color.white;
        button.style.backgroundColor = new Color(0.25f, 0.3f, 0.5f, 1f);
    }
}
