    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        root = doc.rootVisualElement;
        root.Clear();
        root.style.flexGrow = 1;
        root.style.alignItems = Align.Center;
        root.style.justifyContent = Justify.Center;
        root.style.backgroundColor = new Color(0.07f, 0.08f, 0.12f, 1f);

        menuPanel = BuildMenu();
        settingsPanel = BuildSettingsPanel();
        settingsPanel.style.display = DisplayStyle.None;
        root.Add(menuPanel);
        root.Add(settingsPanel);
    }

    private VisualElement BuildMenu()
    {
        VisualElement panel = new VisualElement();
        panel.style.alignItems = Align.Center;

        Label title = new Label("SHADOW RUNNER");
        title.style.fontSize = 72;
        title.style.unityFontStyleAndWeight = FontStyle.Bold;
        title.style.color = Color.white;
        title.style.marginBottom = 50;
        panel.Add(title);

        panel.Add(MakeButton("Play", OnPlay));

        Button continueButton = MakeButton("Continue", OnContinue);
        bool hasSave = PlayerPrefs.GetInt(saveKey, 0) == 1;
        continueButton.SetEnabled(hasSave);
        continueButton.style.opacity = hasSave ? 1f : 0.4f;
        panel.Add(continueButton);

        panel.Add(MakeButton("Settings", () => ShowSettings(true)));
        panel.Add(MakeButton("Quit", OnQuit));
        return panel;
    }

    private VisualElement BuildSettingsPanel()
    {
        VisualElement panel = new VisualElement();
        panel.style.alignItems = Align.Center;

        Label header = new Label("Settings");
        header.style.fontSize = 56;
        header.style.color = Color.white;
        header.style.marginBottom = 30;
        panel.Add(header);

        Toggle muteToggle = new Toggle("Mute audio");
        muteToggle.value = AudioListener.pause;
        muteToggle.style.color = Color.white;
        muteToggle.style.fontSize = 28;
        muteToggle.RegisterValueChangedCallback(evt => AudioListener.pause = evt.newValue);
        panel.Add(muteToggle);

        panel.Add(MakeButton("Back", () => ShowSettings(false)));
        return panel;
    }

    private Button MakeButton(string text, Action onClick)
    {
        Button button = new Button(onClick);
        button.text = text;
        button.style.width = 360;
        button.style.height = 70;
        button.style.fontSize = 30;
        button.style.marginBottom = 14;
        button.style.color = Color.white;
        button.style.backgroundColor = new Color(0.2f, 0.35f, 0.75f, 1f);
        button.style.borderTopLeftRadius = 10;
        button.style.borderTopRightRadius = 10;
        button.style.borderBottomLeftRadius = 10;
        button.style.borderBottomRightRadius = 10;
        return button;
    }

    private void ShowSettings(bool show)
    {
        menuPanel.style.display = show ? DisplayStyle.None : DisplayStyle.Flex;
        settingsPanel.style.display = show ? DisplayStyle.Flex : DisplayStyle.None;
    }

    private void OnPlay()
    {
        PlayerPrefs.SetInt(saveKey, 1);
        PlayerPrefs.Save();
        SceneManager.LoadScene(gameSceneName);
    }

    private void OnContinue()
    {
        SceneManager.LoadScene(gameSceneName);
    }

    private void OnQuit()
    {
        Application.Quit();
    }
}
```

Attach MainMenuUI to an empty GameObject and set the game scene name; the component creates its own UIDocument and PanelSettings at runtime. Continue is created disabled and dimmed unless the PlayerPrefs "HasSave" flag is 1, which Play sets. Settings and the main menu are two panels in the same root that are toggled with display styles.

